@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.tasks.agent-mode=off","dreamcore.tasks.enabled=true"})
class FeedbackIntegrationTest {
 @Autowired com.dreamcore.workspace.lifecycle.MaterialLifecycleService lifecycle; @Autowired com.dreamcore.workspace.lifecycle.MaterialCleanupService cleanup;
 @Autowired JdbcTemplate db;@Autowired FeedbackService service;@Autowired ExperienceService experiences;@Autowired MaterialService materials;@Autowired ProfileService profiles;@Autowired PasswordEncoder passwords;@LocalServerPort int port;
 final JsonMapper json=new JsonMapper();final String password="synthetic-feedback-password";UUID tenant,owner,reader,admin,space,shared,conversation,task,token;
 String email(UUID id){return "feedback-"+id+"@example.test";}
 @BeforeEach void fixture(){tenant=UUID.randomUUID();owner=UUID.randomUUID();reader=UUID.randomUUID();admin=UUID.randomUUID();space=UUID.randomUUID();shared=UUID.randomUUID();conversation=UUID.randomUUID();task=UUID.randomUUID();token=UUID.randomUUID();
  db.update("INSERT INTO tenants(id,name) VALUES (?,'合成反馈企业')",tenant);
  for(UUID a:List.of(owner,reader,admin)){db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,email(a),"合成账号",passwords.encode(password));db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");}
  db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'个人','PERSONAL'),(?,?,?,'共享','SHARED')",space,tenant,owner,shared,tenant,owner);
  db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true),(?,?,?,true)",tenant,shared,owner,tenant,shared,reader);
  db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'合成任务')",conversation,tenant,space,owner);
  db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,engine_version,finished_at) VALUES (?,?,?,?,?,'合成任务提示','AGENT','SUCCEEDED',3,1,'合成回复，不是真实业务成功','verification','test',now())",task,tenant,space,conversation,owner);
  db.update("INSERT INTO conversation_attempts(task_id,attempt_number,attempt_id,input,status,provenance,snapshot) SELECT id,1,?,'合成输入','SUCCEEDED','RECORDED',to_jsonb(t) FROM conversation_tasks t WHERE id=?",token,task);
 }
 FeedbackService.Target target(String kind){return new FeedbackService.Target(kind,task,3,1,kind.equals("BRIEFING")?"briefing-basic-v1":"task-v1",0);}
 FeedbackService.Assessment assessment(String kind){return kind.equals("BRIEFING")?new FeedbackService.Assessment("NOT_USEFUL",List.of("INACCURATE"),"日期需核对"):new FeedbackService.Assessment("PARTIAL",List.of("DATA_GAP"),"资料缺口尚未补齐");}
 FeedbackService.Feedback create(String kind){return service.create(owner,tenant,UUID.randomUUID(),target(kind),assessment(kind));}
 ExperienceService.Content candidate(){return new ExperienceService.Content("CORRECTION","反馈后的日期核对方法","先核对日期再汇总","核对日期、保留资料缺口。",List.of("日期"),"有当前数据","不能将合成回复当业务成功","当前资料版本","人工填写方法；仅以合成流程检查来源关联。","SOURCE_BOUND");}
 UUID[] grantWithoutCitation(){var file=materials.upload(owner,tenant,space,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","source.txt","text/plain","合成原文".getBytes()));UUID version=materials.detail(owner,tenant,space,file.id(),0,20).versions().getFirst().id(),run=UUID.randomUUID(),chunk=UUID.randomUUID();
  db.update("INSERT INTO knowledge_runs(id,tenant_id,workspace_id,material_id,version_id,generation,requested_by,status) VALUES (?,?,?,?,?,1,?,'READY')",run,tenant,space,file.id(),version,owner);
  db.update("INSERT INTO knowledge_chunks(id,tenant_id,workspace_id,material_id,version_id,run_id,ordinal,locator,method,content) VALUES (?,?,?,?,?,?,0,'p1','TEXT','实际读过但未引用')",chunk,tenant,space,file.id(),version,run);
  db.update("INSERT INTO conversation_agent_grants(tenant_id,workspace_id,task_id,attempt_id,chunk_id) VALUES (?,?,?,?,?)",tenant,space,task,token,chunk);return new UUID[]{file.id(),version};
 }
 @Test void twoChannelsHaveDistinctMeaningAndSnapshotWithoutCopyingReply(){var a=create("BRIEFING");var b=create("TASK");assertNotEquals(a.id(),b.id());assertEquals("verification",a.snapshot().executionClass());assertEquals("SUCCEEDED",b.snapshot().taskState());assertFalse(json.writeValueAsString(a).contains("合成回复"));assertEquals("SUCCEEDED",db.queryForObject("SELECT status FROM conversation_tasks WHERE id=?",String.class,task));assertEquals(0,db.queryForObject("SELECT count(*) FROM briefing_preferences WHERE conversation_id=?",Integer.class,conversation));assertEquals(0,db.queryForObject("SELECT count(*) FROM feedback_actions WHERE feedback_id=?",Integer.class,a.id()));}
 @Test void firstSubmissionRejectsChangedTaskAttemptAndPresentation(){db.update("UPDATE conversation_tasks SET revision=4 WHERE id=?",task);assertEquals("FEEDBACK_TARGET_CHANGED",assertThrows(IdentityException.class,()->create("TASK")).code);db.update("UPDATE conversation_tasks SET revision=3 WHERE id=?",task);db.update("INSERT INTO briefing_preferences(tenant_id,workspace_id,conversation_id,owner_id,revision,size) VALUES (?,?,?,?,1,'WIDE')",tenant,space,conversation,owner);assertEquals("FEEDBACK_TARGET_CHANGED",assertThrows(IdentityException.class,()->create("BRIEFING")).code);assertEquals(0,db.queryForObject("SELECT count(*) FROM feedback_entries WHERE tenant_id=?",Integer.class,tenant));}
 @Test void concurrentCreateAndExactRevisionReplaysDoNotOverwriteLaterOpinions() throws Exception {UUID key=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<FeedbackService.Feedback>>of(()->service.create(owner,tenant,key,target("TASK"),assessment("TASK")),()->service.create(owner,tenant,key,target("TASK"),assessment("TASK"))));var f=calls.get(0).get();assertEquals(f,calls.get(1).get());var changed=service.edit(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.Assessment("ACHIEVED",List.of(),"人工补齐后达到目的"),false);assertEquals(2,changed.revision());assertEquals(1,service.create(owner,tenant,key,target("TASK"),assessment("TASK")).revision());assertEquals("FEEDBACK_STATE_CHANGED",assertThrows(IdentityException.class,()->service.edit(owner,tenant,f.id(),UUID.randomUUID(),1,assessment("TASK"),false)).code);assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(IdentityException.class,()->service.create(owner,tenant,key,target("TASK"),new FeedbackService.Assessment("ACHIEVED",List.of(),""))).code);}}
 @Test void withdrawalPreservesHistoryAndStopsNewActionsWithoutChangingTask(){var f=create("TASK");var removed=service.edit(owner,tenant,f.id(),UUID.randomUUID(),1,null,true);assertEquals("WITHDRAWN",removed.status());assertEquals(2,service.history(owner,tenant,f.id(),0,20).items().size());assertEquals("FEEDBACK_STATE_CHANGED",assertThrows(IdentityException.class,()->service.followUp(owner,tenant,f.id(),UUID.randomUUID(),2,new FeedbackService.FollowUp("CORRECTION",true,null,"请核对日期",null))).code);assertEquals("SUCCEEDED",db.queryForObject("SELECT status FROM conversation_tasks WHERE id=?",String.class,task));}
 @Test void readerAndAdminCannotReadOthersFeedbackOrSourceConversation(){var f=create("TASK");for(UUID actor:List.of(reader,admin)){assertThrows(IdentityException.class,()->service.get(actor,tenant,f.id()));assertThrows(IdentityException.class,()->service.lookup(actor,tenant,target("TASK")));}UUID foreign=UUID.randomUUID();db.update("INSERT INTO tenants(id,name) VALUES (?,'其他企业')",foreign);assertThrows(IdentityException.class,()->service.get(owner,foreign,f.id()));}
 @Test void preferenceIsExplicitPersonalEnumActionWithItsOwnVersionAndDeduplication(){var f=create("TASK");var action=new FeedbackService.FollowUp("PREFERENCE",true,new FeedbackService.Preference("WEEKLY_REPORT","CONCLUSION_FIRST",0),null,null);UUID key=UUID.randomUUID();var a=service.followUp(owner,tenant,f.id(),key,1,action);assertEquals("APPLIED",a.status());assertEquals(a,service.followUp(owner,tenant,f.id(),key,1,action));assertEquals(a,service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,action));var p=profiles.get(owner,tenant,a.targetId(),null);assertEquals(ProfileService.Scope.PERSONAL,p.scope());assertEquals(owner,p.subjectId());assertFalse(p.value().contains(f.assessment().suggestion()));service.edit(owner,tenant,f.id(),UUID.randomUUID(),1,null,true);assertEquals("ACTIVE",profiles.get(owner,tenant,a.targetId(),null).effectiveStatus());assertEquals(1,service.actions(owner,tenant,f.id(),0,20).items().size());}
 @Test void correctionCreatesRealWaitingTaskAndAllIndirectSourcesBlockReadAndScrub(){UUID[] source=grantWithoutCitation();var f=create("BRIEFING");assertEquals(1,f.snapshot().sourceVersionCount());var action=new FeedbackService.FollowUp("CORRECTION",true,null,"请核对日期后改为表格，保留未知事项。",null);var a=service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,action);assertEquals("TASK_CREATED",a.status());assertEquals("WAITING_CAPABILITY",a.acceptedState());assertNotEquals(task,a.targetId());assertEquals(1,db.queryForObject("SELECT count(*) FROM feedback_task_sources WHERE task_id=?",Integer.class,a.targetId()));
  lifecycle.act(owner,tenant,space,"MATERIAL",source[0],UUID.randomUUID(),0,"TRASH");assertThrows(IdentityException.class,()->service.get(owner,tenant,f.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id=?",Integer.class,a.targetId()));lifecycle.act(owner,tenant,space,"MATERIAL",source[0],UUID.randomUUID(),1,"PURGE");var job=cleanup.claim();for(UUID object:cleanup.pending(job)){cleanup.remove(object);cleanup.removed(job,object);}cleanup.finish(job);assertEquals("{}",db.queryForObject("SELECT assessment::text FROM feedback_versions WHERE feedback_id=?",String.class,f.id()));assertFalse(db.queryForObject("SELECT prompt FROM conversation_tasks WHERE id=?",String.class,a.targetId()).contains("改为表格"));assertThrows(IdentityException.class,()->lifecycle.act(owner,tenant,space,"MATERIAL",source[0],UUID.randomUUID(),3,"RESTORE"));assertThrows(IdentityException.class,()->service.get(owner,tenant,f.id()));}
 @Test void correctionRemainsSourceBoundWhenSharedGrantIsRevokedWithoutDeletingMaterial(){
  var file=materials.upload(owner,tenant,shared,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","shared-source.txt","text/plain","共享业务原文".getBytes()));
  UUID version=materials.detail(owner,tenant,shared,file.id(),0,20).versions().getFirst().id();db.update("INSERT INTO task_context_materials(task_id,attempt_number,version_id) VALUES (?,1,?)",task,version);
  var f=create("TASK");var correction=service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("CORRECTION",true,null,"保留原文依据进行纠正",null));
  assertEquals(1,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id=?",Integer.class,correction.targetId()));
  db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,shared,owner);
  assertEquals(1,db.queryForObject("SELECT count(*) FROM active_materials WHERE id=?",Integer.class,file.id()));
  assertEquals(0,db.queryForObject("SELECT count(*) FROM readable_source_tasks WHERE id IN (?,?)",Integer.class,task,correction.targetId()));
  assertThrows(IdentityException.class,()->service.get(owner,tenant,f.id()));
 }
 @Test void feedbackCannotCreateManualCandidatesEvenWithExplicitContent(){grantWithoutCitation();var f=create("TASK");var action=new FeedbackService.FollowUp("EXPERIENCE_CANDIDATE",true,null,null,candidate());assertEquals(410,assertThrows(IdentityException.class,()->service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,action)).status);assertEquals(0,db.queryForObject("SELECT count(*) FROM experience_entries WHERE tenant_id=?",Integer.class,tenant));assertEquals(0,db.queryForObject("SELECT count(*) FROM feedback_actions WHERE feedback_id=?",Integer.class,f.id()));}
 @Test void retiredCandidateDoesNotGrantAccessAndCannotChangeTask(){var f=create("TASK");assertEquals(404,assertThrows(IdentityException.class,()->service.followUp(admin,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("EXPERIENCE_CANDIDATE",true,null,null,candidate()))).status);db.update("UPDATE conversation_tasks SET revision=4 WHERE id=?",task);assertEquals(410,assertThrows(IdentityException.class,()->service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("EXPERIENCE_CANDIDATE",true,null,null,candidate()))).status);assertEquals(4,db.queryForObject("SELECT revision FROM conversation_tasks WHERE id=?",Integer.class,task));}
 @Test void malformedRatingAndImplicitActionFailWithoutPersisting(){assertThrows(IdentityException.class,()->service.create(owner,tenant,UUID.randomUUID(),target("BRIEFING"),new FeedbackService.Assessment("NOT_USEFUL",List.of(),"")));assertThrows(IdentityException.class,()->service.create(owner,tenant,UUID.randomUUID(),target("TASK"),new FeedbackService.Assessment("USEFUL",List.of(),"")));var f=create("TASK");assertThrows(IdentityException.class,()->service.followUp(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("PREFERENCE",false,new FeedbackService.Preference("GENERAL","CONCISE",0),null,null)));assertEquals(0,db.queryForObject("SELECT count(*) FROM feedback_actions WHERE feedback_id=?",Integer.class,f.id()));}
 @Test void actualHttpConflictAndAuthorizationErrorsKeepPublicContract()throws Exception{
  var c=new Client();String root="/api/v1/tenants/"+tenant+"/feedback";c.send("POST","/api/v1/auth/login",Map.of("email",email(owner),"password",password),true);
  var f=create("TASK");var changed=service.edit(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.Assessment("ACHIEVED",List.of(),"已人工补齐"),false);
  var stale=c.send("POST",root+"/"+f.id(),Map.of("requestId",UUID.randomUUID(),"expectedRevision",1,"assessment",assessment("TASK")),true);assertEquals(409,stale.statusCode(),stale.body());var error=json.readTree(stale.body());assertEquals("1.0",error.get("contractVersion").asString());assertEquals("FEEDBACK_STATE_CHANGED",error.get("code").asString());assertFalse(error.get("retryable").asBoolean());
  var invalid=c.send("POST",root,Map.of("requestId",UUID.randomUUID(),"target",target("BRIEFING"),"assessment",new FeedbackService.Assessment("NOT_USEFUL",List.of(),"")),true);assertEquals(400,invalid.statusCode(),invalid.body());assertEquals("1.0",json.readTree(invalid.body()).get("contractVersion").asString());
  var other=new Client();other.send("POST","/api/v1/auth/login",Map.of("email",email(admin),"password",password),true);var denied=other.send("GET",root+"/"+f.id(),null,false);assertEquals(404,denied.statusCode(),denied.body());assertEquals("FEEDBACK_NOT_FOUND",json.readTree(denied.body()).get("code").asString());
 }
 @Test void clientHttpDefersExperienceMaintenanceWithoutDeletingInternalHistory() throws Exception {
  var f=create("TASK");var c=new Client();c.send("POST","/api/v1/auth/login",Map.of("email",email(owner),"password",password),true);
  String path="/api/v1/tenants/"+tenant+"/feedback/"+f.id()+"/actions";
  var action=new FeedbackService.FollowUp("EXPERIENCE_CANDIDATE",true,null,null,candidate());
  var response=c.send("POST",path,Map.of("requestId",UUID.randomUUID(),"expectedRevision",1,"action",action),true);
  assertEquals(410,response.statusCode());assertEquals("EXPERIENCE_MANUAL_WORKFLOW_RETIRED",json.readTree(response.body()).get("code").asString());
  assertEquals(0,db.queryForObject("SELECT count(*) FROM feedback_actions WHERE feedback_id=?",Integer.class,f.id()));
  // Preserved historical receipt fixture; retired actions cannot recreate its target.
  var old=experiences.create(owner,tenant,space,UUID.randomUUID(),candidate(),List.of(new ExperienceService.Evidence("TASK",task,space)));
  var historical=new FeedbackService.Action(UUID.randomUUID(),f.id(),1,"EXPERIENCE_CANDIDATE","CANDIDATE_CREATED",old.id(),old.version().id(),1,null,"CANDIDATE","verification",java.time.Instant.now());
  db.update("INSERT INTO feedback_actions(id,feedback_id,feedback_revision,kind,fingerprint,receipt) VALUES (?,?,1,'EXPERIENCE_CANDIDATE','synthetic-legacy',?::jsonb)",historical.id(),f.id(),json.writeValueAsString(historical));
  var correction=service.clientFollowUp(owner,tenant,f.id(),UUID.randomUUID(),1,new FeedbackService.FollowUp("CORRECTION",true,null,"核对当前资料",null));
  assertEquals(2,service.actions(owner,tenant,f.id(),0,20).items().size());
  assertNotNull(experiences.get(owner,tenant,space,historical.targetId(),historical.targetVersion()));
  var clientPage=service.clientActions(owner,tenant,f.id(),0,1);assertEquals(List.of(correction),clientPage.items());assertFalse(clientPage.hasMore());
  assertTrue(service.clientActions(owner,tenant,f.id(),1,1).items().isEmpty());
  var listed=c.send("GET",path,null,false);assertEquals(200,listed.statusCode());assertFalse(listed.body().contains(historical.targetId().toString()));
  assertThrows(IdentityException.class,()->service.clientActions(admin,tenant,f.id(),0,20));
  assertThrows(IdentityException.class,()->service.clientFollowUp(admin,tenant,f.id(),UUID.randomUUID(),1,action));
 }
 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<String> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}}
 @Test void realHttpFeedbackPersistsAndRequiresSessionCsrf()throws Exception{var c=new Client();String root="/api/v1/tenants/"+tenant+"/feedback";var body=Map.of("requestId",UUID.randomUUID(),"target",target("TASK"),"assessment",assessment("TASK"));assertEquals(401,c.send("GET",root+"/preferences",null,false).statusCode());assertEquals(200,c.send("POST","/api/v1/auth/login",Map.of("email",email(owner),"password",password),true).statusCode());assertEquals(403,c.send("POST",root,body,false).statusCode());var response=c.send("POST",root,body,true);assertEquals(201,response.statusCode(),response.body());assertTrue(response.headers().firstValue("cache-control").orElse("").contains("no-store"));UUID id=UUID.fromString(json.readTree(response.body()).get("id").asString());assertEquals(200,c.send("GET",root+"/"+id,null,false).statusCode());}
}
